.hero-offer-card>span:not(.hero-offer-icon)>strong{color:#162033!important}

/* Pricing: independent 4-column grid with equal-height cards and aligned actions. */
#pricing .pricing-grid-clean{display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr))!important;gap:1.15rem!important;align-items:stretch!important;width:100%!important;margin:0!important}
#pricing .pricing-card-clean{display:flex!important;flex-direction:column!important;min-width:0!important;height:100%!important;padding:1.35rem!important;overflow:visible!important}
#pricing .pricing-card-head{display:flex;flex-direction:column;min-width:0}
#pricing .plan-badge{display:inline-flex!important;align-self:flex-start!important;max-width:100%;min-height:30px;margin:0 0 .95rem!important;padding:.36rem .65rem!important;white-space:normal!important;line-height:1.25!important}
#pricing .pricing-title{font-size:clamp(1.18rem,1.6vw,1.48rem)!important;line-height:1.12!important;letter-spacing:-.025em!important;margin:0!important;min-height:2.35em}
#pricing .pricing-dual-price{margin:.9rem 0 .75rem!important;min-height:6.3rem;display:flex;flex-direction:column;justify-content:flex-start}
#pricing .pricing-price{font-size:clamp(1.85rem,2.35vw,2.65rem)!important;line-height:1.02!important;letter-spacing:-.05em!important;overflow-wrap:anywhere}
#pricing .pricing-dual-price .secondary{font-size:1rem!important;line-height:1.3!important;margin-top:.38rem;color:#3e4962!important}
#pricing .pricing-period{font-size:.82rem!important;margin-top:.25rem!important}
#pricing .pricing-intro{font-size:.92rem!important;line-height:1.55!important;margin:0 0 1rem!important;min-height:6.1em}
#pricing .pricing-features{display:grid!important;gap:.62rem!important;margin:0 0 1.15rem!important;flex:1 1 auto!important;align-content:start!important}
#pricing .plan-feature{display:grid!important;grid-template-columns:24px minmax(0,1fr)!important;gap:.5rem!important;align-items:start!important;font-size:.88rem!important;line-height:1.42!important;min-width:0!important}
#pricing .plan-feature-icon{width:24px;height:24px;border-radius:999px;background:#eef0ff;color:#4d50e5;display:grid;place-items:center;margin-top:-1px}
#pricing .plan-feature-icon i{color:inherit!important;font-size:.8rem!important}
#pricing .pricing-action{display:flex!important;align-items:center!important;justify-content:center!important;width:100%!important;min-height:48px!important;margin-top:auto!important;padding:.75rem .8rem!important;text-align:center!important;white-space:normal!important;line-height:1.25!important;box-sizing:border-box!important}

/* Contact: stable grey Leaflet map plus consistently white social glyphs. */
#contact .delivery-map-shell{padding:0!important;min-height:500px!important;height:500px!important;background:#e9edf2!important;overflow:hidden!important;border-radius:28px!important}
#contact .delivery-map-real{display:block!important;width:100%!important;height:500px!important;min-height:500px!important;border:0!important;border-radius:28px!important;overflow:hidden!important;z-index:1}
#contact .delivery-map-real .leaflet-control-attribution{font-size:9px!important;background:rgba(255,255,255,.78)!important}
#contact .contact-social-link{background:#1f2638!important;color:#fff!important;border:1px solid #1f2638!important}
#contact .contact-social-link i,
#contact .contact-social-link .bi,
#contact .contact-social-link .bi:before,
#contact .contact-social-link .cms-external-icon,
#contact .contact-social-link .cms-external-icon-fallback{color:#fff!important}
#contact .contact-social-link .cms-live-icon{background:#fff!important;color:#fff!important}
#contact .contact-social-link:hover{background:#111827!important;color:#fff!important;border-color:#111827!important}

@media(max-width:1199.98px){
  #pricing .pricing-grid-clean{grid-template-columns:repeat(2,minmax(0,1fr))!important}
  #pricing .pricing-title,#pricing .pricing-dual-price,#pricing .pricing-intro{min-height:0}
}
@media(max-width:767.98px){
  #pricing .pricing-grid-clean{grid-template-columns:1fr!important;gap:1rem!important}
  #pricing .pricing-card-clean{padding:1.2rem!important}
  #contact .delivery-map-shell,#contact .delivery-map-real{height:360px!important;min-height:360px!important}
}
